// Preenche os links de contato no header e na seção de contato
function setupSocialLinks() {
  const { github, linkedin, email } = SOCIAL_LINKS;

  const githubEls = [document.getElementById('githubLink'), document.getElementById('githubLink2')];
  const linkedinEls = [document.getElementById('linkedinLink'), document.getElementById('linkedinLink2')];
  const emailEl = document.getElementById('emailLink');

  if (github) {
    githubEls.forEach((el) => el && (el.href = github));
    const label = document.getElementById('githubLink2')?.querySelector('strong');
    if (label) label.textContent = `@${github.split('/').filter(Boolean).pop()}`;
  }
  if (linkedin) {
    linkedinEls.forEach((el) => el && (el.href = linkedin));
  }
  if (email && emailEl) {
    emailEl.href = `mailto:${email}`;
    const label = emailEl.querySelector('strong');
    if (label) label.textContent = email;
  }
}

// Coloca a foto de perfil no Hero (imagem embutida em base64, sem depender de pasta)
function setupHeroPhoto() {
  const img = document.getElementById('heroPhoto');
  if (img && IMAGES.profile) img.src = IMAGES.profile;
}

// Header muda de fundo ao rolar a página
function setupHeaderScroll() {
  const header = document.getElementById('header');
  const updateHeader = () => {
    if (window.scrollY > 12) header.classList.add('scrolled');
    else header.classList.remove('scrolled');
  };
  window.addEventListener('scroll', updateHeader, { passive: true });
  updateHeader();
}

// Menu mobile
function setupMobileMenu() {
  const btn = document.getElementById('menuBtn');
  const links = document.getElementById('navLinks');
  const closeMenu = () => {
    links.classList.remove('open');
    btn.classList.remove('open');
    btn.setAttribute('aria-expanded', 'false');
    btn.setAttribute('aria-label', 'Abrir menu');
  };

  btn.addEventListener('click', () => {
    const isOpen = links.classList.toggle('open');
    btn.classList.toggle('open', isOpen);
    btn.setAttribute('aria-expanded', String(isOpen));
    btn.setAttribute('aria-label', isOpen ? 'Fechar menu' : 'Abrir menu');
  });
  links.querySelectorAll('a').forEach((link) => link.addEventListener('click', closeMenu));
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeMenu();
  });
  window.addEventListener('resize', () => {
    if (window.innerWidth > 760) closeMenu();
  });
}

// Renderiza os cards de projeto a partir do array PROJECTS
function renderProjects() {
  const grid = document.getElementById('projectsGrid');
  if (!grid) return;

  grid.innerHTML = PROJECTS.map((project, index) => {
    const coverSrc = IMAGES[project.cover] || '';
    const featuredClass = index === 0 ? 'featured' : '';
    const githubLabel = project.githubUrl ? project.githubUrl.replace('https://', '') : '';
    const techBadges = project.stack.map((t) => `<span class="tech">${t}</span>`).join('');

    return `
      <article class="project-card ${featuredClass}" data-project-id="${project.id}" tabindex="0" role="button" aria-label="Ver detalhes do projeto ${project.name}">
        <div class="project-image">
          <img src="${coverSrc}" alt="Captura de tela do projeto ${project.name}" loading="lazy" />
          <span class="view-details">Ver detalhes →</span>
        </div>
        <div class="project-body">
          <div class="project-top">
            <span class="tag">${project.tag}</span>
            <span class="mono-small">${githubLabel}</span>
          </div>
          <h3>${project.name}</h3>
          <p class="project-desc">${project.description}</p>
          <div class="badges">${techBadges}</div>
        </div>
      </article>
    `;
  }).join('');

  grid.querySelectorAll('.project-card').forEach((card) => {
    const open = () => openProjectModal(card.dataset.projectId);
    card.addEventListener('click', open);
    card.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        open();
      }
    });
  });
}

// ============================================
// MODAL DE DETALHES DO PROJETO
// ============================================
let currentGallery = [];
let currentImageIndex = 0;
let currentProjectName = '';
let lastFocusedElement = null;

function openProjectModal(projectId) {
  const project = PROJECTS.find((p) => p.id === projectId);
  if (!project) return;

  document.getElementById('modalTag').textContent = project.tag;
  document.getElementById('modalTitle').textContent = project.name;
  document.getElementById('modalDesc').textContent = project.description;
  document.getElementById('modalProblem').textContent = project.problem;
  document.getElementById('modalSolution').textContent = project.solution;
  document.getElementById('modalRole').textContent = project.role;
  document.getElementById('modalStack').innerHTML = project.stack
    .map((t) => `<span class="tech">${t}</span>`)
    .join('');

  const githubEl = document.getElementById('modalGithub');
  githubEl.textContent = project.githubUrl ? project.githubUrl.replace('https://', '') : '';

  currentGallery = project.gallery.map((key) => IMAGES[key]).filter(Boolean);
  currentImageIndex = 0;
  currentProjectName = project.name;
  renderModalGallery();

  const modal = document.getElementById('projectModal');
  lastFocusedElement = document.activeElement;
  modal.hidden = false;
  document.body.classList.add('modal-open');
  document.getElementById('modalClose').focus();
}

function renderModalGallery() {
  const mainImg = document.getElementById('modalMainImg');
  mainImg.src = currentGallery[currentImageIndex] || '';
  mainImg.alt = currentGallery.length
    ? `Tela ${currentImageIndex + 1} do projeto ${currentProjectName}`
    : '';

  const thumbs = document.getElementById('modalThumbs');
  if (currentGallery.length <= 1) {
    thumbs.innerHTML = '';
    thumbs.style.display = 'none';
    return;
  }
  thumbs.style.display = 'flex';
  thumbs.innerHTML = currentGallery
    .map(
      (src, i) =>
        `<button class="modal-thumb ${i === currentImageIndex ? 'active' : ''}" data-index="${i}" aria-label="Ver tela ${i + 1} de ${currentGallery.length}"><img src="${src}" alt="" /></button>`
    )
    .join('');

  thumbs.querySelectorAll('.modal-thumb').forEach((btn) => {
    btn.addEventListener('click', () => {
      currentImageIndex = Number(btn.dataset.index);
      renderModalGallery();
    });
  });
}

function closeProjectModal() {
  const modal = document.getElementById('projectModal');
  if (modal.hidden) return;
  modal.hidden = true;
  document.body.classList.remove('modal-open');
  if (lastFocusedElement instanceof HTMLElement) lastFocusedElement.focus();
}

function setupModal() {
  const modal = document.getElementById('projectModal');
  document.getElementById('modalClose').addEventListener('click', closeProjectModal);
  modal.addEventListener('click', (e) => {
    if (e.target === modal) closeProjectModal();
  });
  document.addEventListener('keydown', (e) => {
    if (modal.hidden) return;
    if (e.key === 'Escape') closeProjectModal();
    if (e.key === 'ArrowRight' && currentGallery.length > 1) {
      currentImageIndex = (currentImageIndex + 1) % currentGallery.length;
      renderModalGallery();
    }
    if (e.key === 'ArrowLeft' && currentGallery.length > 1) {
      currentImageIndex = (currentImageIndex - 1 + currentGallery.length) % currentGallery.length;
      renderModalGallery();
    }
    if (e.key === 'Tab') {
      const focusable = [...modal.querySelectorAll('button:not([disabled]), a[href]')];
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });
}

// Animação de revelar elementos ao rolar a página
function setupScrollReveal() {
  const items = document.querySelectorAll('.reveal');
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  if (prefersReducedMotion) {
    items.forEach((el) => el.classList.add('visible'));
    return;
  }

  if (!('IntersectionObserver' in window)) {
    items.forEach((el) => el.classList.add('visible'));
    return;
  }

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.1, rootMargin: '0px 0px -60px 0px' }
  );

  items.forEach((el) => observer.observe(el));
}

function setupYear() {
  const el = document.getElementById('year');
  if (el) el.textContent = new Date().getFullYear();
}

document.addEventListener('DOMContentLoaded', () => {
  setupSocialLinks();
  setupHeroPhoto();
  setupHeaderScroll();
  setupMobileMenu();
  renderProjects();
  setupModal();
  setupScrollReveal();
  setupYear();
});
